/**
 * Real-Chromium check of the numbering OUTCOME: "Figure 1." / "Table 1." are
 * generated by CSS counters, which a string assertion on the stylesheet
 * (captionNumbering.test.ts) cannot show working, and which getComputedStyle
 * cannot resolve either (it returns the unevaluated `counter(...)` text).
 * The rendered text is read back through the DevTools DOMSnapshot, whose layout
 * text boxes include generated content, in document order -- what a reader sees.
 *
 * Pins: titled figures and tables count separately; an untitled figure or table
 * is not counted; the count restarts at each top-level topic (as in a Book page
 * of many topics) while a nested topic continues its parent's count; and the
 * label words follow the topic's xml:lang (图 / 表 for zh). Needs the
 * downloaded Chromium (`npm run playwright:install`); run with
 * `npm run test:visual`.
 */
import * as assert from 'assert';
import { readFileSync } from 'fs';
import { join, resolve } from 'path';
import { chromium, type Browser } from 'playwright';
import { renderTopicXml } from '../editor/ditaRenderUtils';

const baseCss = readFileSync(join(resolve(__dirname, '..', '..'), 'media', 'styles.css'), 'utf-8');

const tbl = (t: string): string =>
  `<table>${t ? `<title>${t}</title>` : ''}<tgroup cols="1"><tbody><row><entry>cell</entry></row></tbody></tgroup></table>`;
const fig = (t: string): string => `<fig>${t ? `<title>${t}</title>` : ''}<image href="a.png" alt="i"/></fig>`;
const topic = (id: string, lang: string, body: string, nested = ''): string =>
  `<topic id="${id}"${lang ? ` xml:lang="${lang}"` : ''}><title>Topic ${id}</title><body>${body}</body>${nested}</topic>`;

function render(xml: string): string {
  return renderTopicXml({
    xml,
    docDir: resolve(__dirname),
    keyMap: new Map(),
    asWebviewUri: (p) => p,
    headingLevel: 1,
    uiLanguage: 'en',
  }).html;
}

describe('figure and table numbering (real Chromium)', function () {
  this.timeout(60000);
  let browser: Browser;

  before(async () => {
    browser = await chromium.launch();
  });
  after(async () => {
    if (browser) await browser.close();
  });

  /** The generated captions, in order, as one string each: "Figure 1. Title". */
  async function captions(bodyHtml: string): Promise<string[]> {
    const page = await browser.newPage();
    try {
      await page.setContent(
        `<!doctype html><html lang="en"><head><style>${baseCss}</style></head><body>${bodyHtml}</body></html>`,
      );
      const cdp = await page.context().newCDPSession(page);
      const snap = (await cdp.send('DOMSnapshot.captureSnapshot', { computedStyles: [] })) as {
        strings: string[];
        documents: { layout: { text: number[] } }[];
      };
      const tokens = snap.documents
        .flatMap((d) => d.layout.text)
        .filter((t) => t >= 0)
        .map((t) => snap.strings[t]);
      // Each generated caption is four text boxes: label, number, ". ", then the title.
      const out: string[] = [];
      for (let i = 0; i + 3 < tokens.length; i++) {
        if (/^(Figure|Table|图|圖|表) $/.test(tokens[i]) && /^\d+$/.test(tokens[i + 1]) && tokens[i + 2] === '. ') {
          out.push(`${tokens[i]}${tokens[i + 1]}. ${tokens[i + 3]}`);
          i += 3;
        }
      }
      return out;
    } finally {
      await page.close();
    }
  }

  it('numbers titled figures and tables separately, skipping untitled ones', async () => {
    const out = await captions(render(topic('A', '', fig('F1') + tbl('T1') + fig('') + tbl('') + fig('F2') + tbl('T2'))));
    assert.deepStrictEqual(out, ['Figure 1. F1', 'Table 1. T1', 'Figure 2. F2', 'Table 2. T2']);
  });

  it('a nested topic continues the count', async () => {
    const out = await captions(render(topic('A', '', fig('F1'), topic('N', '', fig('F2') + tbl('T1')))));
    assert.deepStrictEqual(out, ['Figure 1. F1', 'Figure 2. F2', 'Table 1. T1']);
  });

  it('restarts at each top-level topic (a Book page of several topics)', async () => {
    const out = await captions(render(topic('A', '', fig('F1') + tbl('T1'))) + render(topic('B', '', fig('F1') + tbl('T1'))));
    assert.deepStrictEqual(out, ['Figure 1. F1', 'Table 1. T1', 'Figure 1. F1', 'Table 1. T1']);
  });

  it('uses 圖 / 表 for Traditional Chinese (zh-TW, zh-Hant), not the simplified 图', async () => {
    const out = await captions(render(topic('A', 'zh-TW', fig('F1') + tbl('T1'))) + render(topic('B', 'zh-Hant', fig('F1'))));
    assert.deepStrictEqual(out, ['圖 1. F1', '表 1. T1', '圖 1. F1']);
  });

  it('uses 图 / 表 for a topic with xml:lang="zh-CN", English otherwise', async () => {
    const out = await captions(render(topic('A', 'zh-CN', fig('F1') + tbl('T1'))) + render(topic('B', '', fig('F1'))));
    assert.deepStrictEqual(out, ['图 1. F1', '表 1. T1', 'Figure 1. F1']);
  });
});
